const USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v";
const JUP  = "JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN";
const SOL  = "So11111111111111111111111111111111111111112";

async function jq(url){ const r = await fetch(url); return r.json(); }

try {
  const price = await jq("https://price.jup.ag/v6/price?ids=SOL,JUP");
  console.log("PRICE", JSON.stringify(price));

  const q1 = await jq(`https://quote-api.jup.ag/v6/quote?inputMint=${USDC}&outputMint=${JUP}&amount=100000000&slippageBps=10`);
  console.log("USDC->JUP out:", q1.outAmount, "impact:", q1.priceImpactPct, "route:", (q1.routePlan||[]).map(r=>r.swapInfo.label).join("|"));

  const q2 = await jq(`https://quote-api.jup.ag/v6/quote?inputMint=${JUP}&outputMint=${USDC}&amount=${q1.outAmount}&slippageBps=10`);
  console.log("JUP->USDC out:", q2.outAmount, "impact:", q2.priceImpactPct, "route:", (q2.routePlan||[]).map(r=>r.swapInfo.label).join("|"));

  const net = Number(q2.outAmount) - 100000000;
  console.log("NET raw USDC on 100 USDC roundtrip:", net, "=", net/1e6, "USD");
} catch(e){ console.log("ERR", e.message); }

const USDC = "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v";
const JUP  = "JUPyiwrYJFskUPiHa7hkeR8VUtAeFoSYbKedZNsDvCN";

async function tryFetch(url){
  try {
    const c = new AbortController();
    const t = setTimeout(()=>c.abort(), 8000);
    const r = await fetch(url, {signal:c.signal});
    clearTimeout(t);
    const txt = await r.text();
    return {ok:r.ok, status:r.status, body:txt.slice(0,400)};
  } catch(e){ return {ok:false, err:e.message}; }
}

const endpoints = [
  "https://lite-api.jup.ag/swap/v1/quote?inputMint="+USDC+"&outputMint="+JUP+"&amount=100000000&slippageBps=10",
  "https://quote-api.jup.ag/v6/quote?inputMint="+USDC+"&outputMint="+JUP+"&amount=100000000&slippageBps=10",
  "https://price.jup.ag/v6/price?ids=SOL,JUP",
  "https://api.mainnet-beta.solana.com",
];

for (const u of endpoints){
  const r = await tryFetch(u);
  console.log("URL", u.slice(0,60), "=>", JSON.stringify(r));
}
